private static void cleanupCache(){
  KylinConfig config = null;
  try {
    config = KylinConfig.getInstanceFromEnv();
  } catch (SecurityException | NullPointerException e) {
    System.err.println("Error initializing KylinConfig: " + e.getMessage());
    e.printStackTrace();
    return;
  }
  for (String serviceClass : SERVICES_WITH_CACHE) {
    try {
      Class<?> cls = Class.forName(serviceClass);
      Method method = cls.getDeclaredMethod("removeInstance", KylinConfig.class);
      method.invoke(null, config);
    } catch (ClassNotFoundException e) {
      // Ignore class not found
    } catch (ExceptionInInitializerError | InvocationTargetException | LinkageError | SecurityException e) {
      System.err.println("Error cleaning up cache for " + serviceClass + ": " + e.getMessage());
      e.printStackTrace();
    }
  }
}
